 const shared={}, worldPreview={get state(){return state();}}, CITIES=[{"id":"seoul"},{"id":"tokyo"},{"id":"shanghai"},{"id":"bangkok"},{"id":"manila"},{"id":"la"},{"id":"nyc"},{"id":"saopaulo"},{"id":"london"},{"id":"paris"},{"id":"rome"},{"id":"sydney"}];
