/* Scene motion in original artwork coordinates. The parent applies the exact
   city-transition mask first. Drawing at half CSS resolution gives crisp,
   stepped game pixels instead of fluid particles or cinematic blur. */
function drawLegacyMotion(c,img,city,time,ox,oy,scale){
 c.save();c.globalAlpha=1;c.translate(ox,oy);c.scale(scale,scale);
 if(city==='tokyo'){
  const phase=time%14600,front=150+(phase-1000)/7000*1100;
  canvas.dataset.train=phase>=1000&&phase<8500?'passing':'between-trains';
  if(phase>=1000&&phase<8500){
   // Pass behind the three window openings and the right-hand plant.
   c.beginPath();c.rect(220,690,55,160);c.rect(295,690,342,180);c.rect(654,690,121,185);c.clip();
   c.transform(1,.108,0,1,0,729);
   const lead=Math.round(front/3)*3;
   for(let car=0;car<3;car++){
    const x=lead-91*(car+1),w=87;
    // Roof, orange body, pale lower panel, blue skirt, doors and lit windows.
    c.fillStyle='#101634';c.fillRect(x-1,-30,w+2,27);
    c.fillStyle='#34446b';c.fillRect(x+3,-32,w-6,4);
    c.fillStyle='#b8bfce';c.fillRect(x,-27,w,22);
    c.fillStyle='#d86b32';c.fillRect(x,-25,w,16);
    c.fillStyle='#858ba7';c.fillRect(x,-9,w,4);
    c.fillStyle='#252d60';c.fillRect(x,-5,w,3);
    for(let j=0;j<7;j++){
     const wx=x+5+j*11;
     c.fillStyle='#ffce79';c.fillRect(wx,-23,8,11);
     c.fillStyle=j%3===1?'#fff3bf':'#ffe6a3';c.fillRect(wx+1,-22,5,9);
     if(j===2||j===5){c.fillStyle='#b8b7bc';c.fillRect(wx+7,-24,1,18);}
    }
    c.fillStyle='#11162e';c.fillRect(x+9,-2,9,3);c.fillRect(x+w-19,-2,9,3);
    if(car===0){c.fillStyle='#283253';c.fillRect(x+w-7,-24,7,16);c.fillStyle='#e6efff';c.fillRect(x+w-5,-22,4,7);c.fillStyle='#fff1b3';c.fillRect(x+w-3,-9,3,2);}
    if(car===2){c.fillStyle='#e26959';c.fillRect(x,-10,2,2);}
   }
  }
 }else if(city==='la'){
  // Open water only: the pier, shore palms, window sill and equipment mask it.
  c.beginPath();c.moveTo(158,833);c.lineTo(409,834);c.lineTo(409,865);c.lineTo(604,869);c.lineTo(661,879);c.lineTo(580,895);c.lineTo(465,919);c.lineTo(374,937);c.lineTo(346,936);c.lineTo(344,916);c.lineTo(326,900);c.lineTo(305,899);c.lineTo(291,915);c.lineTo(274,924);c.lineTo(245,919);c.lineTo(224,910);c.lineTo(198,907);c.lineTo(193,890);c.lineTo(158,890);c.closePath();c.clip();
  const step=Math.floor(time/160);
  // Small integer displacements make the painted sea itself move, not just dots.
  c.imageSmoothingEnabled=false;
  for(let y=832;y<942;y+=4){const dx=Math.round(Math.sin(y*.15+step*.37)*2);c.drawImage(img,153,y,520,4,153+dx,y,520,4);}
  const cycle=(time%5200)/5200;
  for(let wave=0;wave<6;wave++){
   const age=(cycle+wave/6)%1,base=833+age*111;
   c.globalAlpha=(.2+.32*Math.sin(age*Math.PI));
   c.fillStyle=['#ffd47b','#ffe8a0','#fff1ba'][Math.floor(age*3)];
   for(let x=160;x<665;x+=17){const y=base-.00022*(x-160)*(x-160)+Math.sin(x*.055+wave)*1.5;const gap=(Math.floor(x/17)+wave)%5;if(gap===0)continue;c.fillRect(x,Math.round(y/2)*2,9+(gap%3)*3,2);}
  }
  // The sunset reflection changes in held color frames, without flashes.
  for(let i=0;i<18;i++){const y=836+i*5,x=241+Math.sin(i*2.3+Math.floor(step/3))*(6+i*.65);c.globalAlpha=.22+(i%3)*.08;c.fillStyle=['#ffd58a','#fff0ad','#ffb959'][(i+Math.floor(step/3))%3];c.fillRect(Math.round(x/2)*2,y,6+i*.35,2);}
  canvas.dataset.surfFrame=String(step);
 }else if(city==='seoul'){
  // Apartment lights hold for seconds; the tower beacon takes one quiet beat.
  const windows=[[122,590],[145,610],[249,640],[337,642],[355,663],[513,747],[593,702],[817,686]];
  for(let i=0;i<windows.length;i++){
   const [x,y]=windows[i],on=(Math.floor((time+i*1700)/5100)%4)!==0;
   c.globalAlpha=on?.46:.24;c.fillStyle=on?'#ffe1a1':'#172542';c.fillRect(x,y,3,5);
  }
  const beat=Math.floor(time/300)%14;c.globalAlpha=beat<3?.65:.14;c.fillStyle=beat<3?'#ff9484':'#cf5d69';c.fillRect(723,507,3,3);
 }
 c.restore();
}

